// LoadCashRegister allows an eager lookup of values, cached into the
// loaded structs of the objects. This is for an N-1 relationship.
func (payIncomeL) LoadCashRegister(ctx context.Context, e boil.ContextExecutor, singular bool, maybePayIncome any, mods queries.Applicator) error {
	var slice []*PayIncome
	var object *PayIncome

	if singular {
		var ok bool
		object, ok = maybePayIncome.(*PayIncome)
		if !ok {
			object = new(PayIncome)
			ok = queries.SetFromEmbeddedStruct(&object, &maybePayIncome)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", object, maybePayIncome))
			}
		}
	} else {
		s, ok := maybePayIncome.(*[]*PayIncome)
		if ok {
			slice = *s
		} else {
			ok = queries.SetFromEmbeddedStruct(&slice, maybePayIncome)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", slice, maybePayIncome))
			}
		}
	}

	args := make(map[any]struct{})
	if singular {
		if object.R == nil {
			object.R = &payIncomeR{}
		}
		if !queries.IsNil(object.CashRegisterID) {
			args[object.CashRegisterID] = struct{}{}
		}

	} else {
		for _, obj := range slice {
			if obj.R == nil {
				obj.R = &payIncomeR{}
			}

			if !queries.IsNil(obj.CashRegisterID) {
				args[obj.CashRegisterID] = struct{}{}
			}

		}
	}

	if len(args) == 0 {
		return nil
	}

	argsSlice := make([]any, len(args))
	i := 0
	for arg := range args {
		argsSlice[i] = arg
		i++
	}

	query := NewQuery(
		qm.From(`cash_registers`),
		qm.WhereIn(`cash_registers.id in ?`, argsSlice...),
	)
	if mods != nil {
		mods.Apply(query)
	}

	results, err := query.QueryContext(ctx, e)
	if err != nil {
		return errors.Wrap(err, "failed to eager load CashRegister")
	}

	var resultSlice []*CashRegister
	if err = queries.Bind(results, &resultSlice); err != nil {
		return errors.Wrap(err, "failed to bind eager loaded slice CashRegister")
	}

	if err = results.Close(); err != nil {
		return errors.Wrap(err, "failed to close results of eager load for cash_registers")
	}
	if err = results.Err(); err != nil {
		return errors.Wrap(err, "error occurred during iteration of eager loaded relations for cash_registers")
	}

	if len(cashRegisterAfterSelectHooks) != 0 {
		for _, obj := range resultSlice {
			if err := obj.doAfterSelectHooks(ctx, e); err != nil {
				return err
			}
		}
	}

	if len(resultSlice) == 0 {
		return nil
	}

	if singular {
		foreign := resultSlice[0]
		object.R.CashRegister = foreign
		if foreign.R == nil {
			foreign.R = &cashRegisterR{}
		}
		foreign.R.PayIncomes = append(foreign.R.PayIncomes, object)
		return nil
	}

	for _, local := range slice {
		for _, foreign := range resultSlice {
			if queries.Equal(local.CashRegisterID, foreign.ID) {
				local.R.CashRegister = foreign
				if foreign.R == nil {
					foreign.R = &cashRegisterR{}
				}
				foreign.R.PayIncomes = append(foreign.R.PayIncomes, local)
				break
			}
		}
	}

	return nil
}

